p='infrastructure/in-memory.ts'
s=open(p).read()
s=s.replace('import { Booking,','import { AuditEntry, Booking,')
s=s.replace('  BookingRepository,','  AuditLogRepository,\n  BookingRepository,',1)
s=s.replace('  SettlementRepository,\n','  SettlementRepository,\n  UnitOfWork,\n',1)
# snapshot support
s=s.replace('export class InMemoryMarketDays','''interface Snapshottable {
  snapshot(): () => void;
}

const copy = <T>(v: T): T => structuredClone(v);

export class InMemoryMarketDays''',1)
def addsnap(cls, field, kind):
    global s
    i=s.index('export class '+cls)
    j=s.index('{\n',i)+2
    if kind=='map':
        code=f'  snapshot() {{ const saved = new Map(this.{field}); return () => {{ this.{field} = saved; }}; }}\n'
    else:
        code=f'  snapshot() {{ const saved = [...this.{field}]; return () => {{ this.{field} = saved; }}; }}\n'
    # find end of field line
    k=s.index('\n',s.index('private',j))+1
    s=s[:k]+code+s[k:]
for c,f,k in [('InMemoryMarketDays','items','map'),('InMemoryPitches','items','map'),('InMemoryVendors','items','map'),('InMemoryBookings','items','arr'),('InMemoryReaderLinks','items','map'),('InMemoryMerchantLinks','items','map'),('InMemoryCardSales','items','arr'),('InMemorySettlements','items','arr'),('InMemoryVendorBalances','items','map')]:
    addsnap(c,f,k)
s=s.replace('  get() { return { ...this.schedule }; }','  snapshot() { const saved = this.schedule; return () => { this.schedule = saved; }; }\n  get() { return { ...this.schedule }; }')
s=s.replace('  listByDay(marketDayId: string) { return this.items.filter((s) => s.marketDayId === marketDayId); }\n}','  listByDay(marketDayId: string) { return this.items.filter((s) => s.marketDayId === marketDayId); }\n  listByVendor(vendorId: string) { return this.items.filter((s) => s.vendorId === vendorId); }\n}')
s=s.replace('  listByDay(marketDayId: string) { return this.items.filter((b) => b.marketDayId === marketDayId); }','  listByDay(marketDayId: string) { return this.items.filter((b) => b.marketDayId === marketDayId); }\n  listByVendor(vendorId: string) { return this.items.filter((b) => b.vendorId === vendorId); }')
# map snapshots shallow: updates replace objects, fine (service never mutates in place)
s+='''
export class InMemoryAuditLog implements AuditLogRepository {
  private items: AuditEntry[] = [];
  snapshot() { const saved = [...this.items]; return () => { this.items = saved; }; }
  add(entry: AuditEntry) { this.items.push(copy(entry)); }
  listByDay(marketDayId: string) { return this.items.filter((e) => e.marketDayId === marketDayId).map(copy); }
}

/** Snapshots every registered store before the work and restores them all if the work throws. */
export class InMemoryUnitOfWork implements UnitOfWork {
  private depth = 0;
  constructor(private readonly stores: Snapshottable[]) {}
  run<T>(work: () => T): T {
    if (this.depth > 0) return work();
    const restores = this.stores.map((st) => st.snapshot());
    this.depth++;
    try {
      return work();
    } catch (e) {
      for (const restore of restores) restore();
      throw e;
    } finally {
      this.depth--;
    }
  }
}
'''
